    elseif power = 6 then [1.23, 3.41]
    elseif power = 7 then [1.18, 3.27]  
    elseif power = 8 then [1.16, 3.18] 
    elseif power = 9 then [1.13, 3.11]  
    elseif power = 10 then [1.12, 3.06] 
    elseif power = 11 then [1.11, 3.02]
    elseif power = 12 then [1.10, 2.99] 
    elseif power = 13 then [1.09, 2.97] 
    elseif power = 14 then [1.08, 2.95] 
    elseif power = 15 then [1.07, 2.93]
    elseif power = 16 then [1.07, 2.91]
    elseif power = 17 then [1.06, 2.90];
x_cord:point[1];
